select c1.C_Name as ppFeasibilityUnitName, c1.C_Name_History as ppFeasibilityUnitNameHistory, c2.C_Name as ppEstimationUnitName, c2.C_Name_History as ppEstimationUnitNameHistory, c1.C_Abbreviation as ppFeasibilityAbbName, c2.C_Abbreviation as ppEstimationAbbName, sd.D_Name as ppDepName, mn.* from Pre_Pro_Proposal mn left join Sys_Company c1 on c1.C_Id=mn.Pp_Feasibility_Unit_Id left join Sys_Company c2 on c2.C_Id=mn.Pp_Estimation_Unit_Id left join SYS_Department sd on sd.D_Id=mn.Pp_Department ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pp_Create_Time DESC
